namespace LocalAI.Desktop;
internal static class DarkTheme
{
    [StructLayout(LayoutKind.Sequential)] private struct NativeRect {public int Left,Top,Right,Bottom;}
    [StructLayout(LayoutKind.Sequential)] private struct MonitorInfo {public int Size;public NativeRect Monitor,Work;public uint Flags;}
    [DllImport("user32.dll")] private static extern nint MonitorFromWindow(nint window,uint flags);
    [DllImport("user32.dll")] [return:MarshalAs(UnmanagedType.Bool)] private static extern bool GetMonitorInfo(nint monitor,ref MonitorInfo info);
    internal static void ConstrainToWorkArea(Window window,Rect area)
    {
        window.MinWidth=Math.Min(window.MinWidth,area.Width);window.MinHeight=Math.Min(window.MinHeight,area.Height);
        window.MaxWidth=Math.Min(window.MaxWidth,area.Width);window.MaxHeight=Math.Min(window.MaxHeight,area.Height);
        if(!double.IsNaN(window.Width))window.Width=Math.Min(window.Width,area.Width);
        if(!double.IsNaN(window.Height))window.Height=Math.Min(window.Height,area.Height);
        if(window.IsLoaded&&window.WindowState==WindowState.Normal){window.Left=Math.Clamp(window.Left,area.Left,Math.Max(area.Left,area.Right-window.ActualWidth));window.Top=Math.Clamp(window.Top,area.Top,Math.Max(area.Top,area.Bottom-window.ActualHeight));}
    }
    private static void FitWorkArea(Window window)
    {
        var info=new MonitorInfo{Size=Marshal.SizeOf<MonitorInfo>()};var handle=new WindowInteropHelper(window.Owner??window).Handle;
        var dpi=VisualTreeHelper.GetDpi(window);var area=SystemParameters.WorkArea;
        if(GetMonitorInfo(MonitorFromWindow(handle,2),ref info))area=new Rect(info.Work.Left/dpi.DpiScaleX,info.Work.Top/dpi.DpiScaleY,(info.Work.Right-info.Work.Left)/dpi.DpiScaleX,(info.Work.Bottom-info.Work.Top)/dpi.DpiScaleY);
        ConstrainToWorkArea(window,area);
    }
    public static void Apply(Window window)
    {
        window.Icon=System.Windows.Media.Imaging.BitmapFrame.Create(new Uri("pack://application:,,,/Assets/infinity.ico"));
        window.Background=new SolidColorBrush(Color.FromRgb(16,19,24));window.Foreground=new SolidColorBrush(Color.FromRgb(230,235,245));
        window.Resources.MergedDictionaries.Add((ResourceDictionary)XamlReader.Parse(Styles));
        window.WindowStyle=WindowStyle.None;
        WindowChrome.SetWindowChrome(window,new WindowChrome{CaptionHeight=0,ResizeBorderThickness=new Thickness(6),GlassFrameThickness=new Thickness(0),CornerRadius=new CornerRadius(0),UseAeroCaptionButtons=false});
    }
    public static void Wrap(Window window,UIElement content)
    {
        window.SourceInitialized+=(_,_)=>FitWorkArea(window);window.Loaded+=(_,_)=>FitWorkArea(window);
        var shell=new DockPanel{Background=window.Background};
        var caption=new DockPanel{Background=window.Background,Height=40,LastChildFill=true};DockPanel.SetDock(caption,Dock.Top);shell.Children.Add(caption);
        foreach(var (label,action) in new (string,Action)[]{("×",window.Close),("□",()=>window.WindowState=window.WindowState==WindowState.Maximized?WindowState.Normal:WindowState.Maximized),("−",()=>window.WindowState=WindowState.Minimized)})
        {var button=new Button{Content=label,Tag=label=="×"?"Close window":label=="□"?"Maximize / restore":"Minimize",Width=44,FontSize=18,Margin=new Thickness(0),Padding=new Thickness(0)};System.Windows.Automation.AutomationProperties.SetName(button,(string)button.Tag);button.Click+=(_,_)=>action();DockPanel.SetDock(button,Dock.Right);caption.Children.Add(button);}
        var title=new TextBlock{Text=window.Title,VerticalAlignment=VerticalAlignment.Center,Margin=new Thickness(16,0,0,0),Foreground=window.Foreground};caption.Children.Add(title);
        title.MouseLeftButtonDown+=(_,e)=>{if(e.ClickCount==2)window.WindowState=window.WindowState==WindowState.Maximized?WindowState.Normal:WindowState.Maximized;else if(e.ButtonState==MouseButtonState.Pressed)window.DragMove();};
        shell.Children.Add(content);window.Content=new Border{BorderBrush=new SolidColorBrush(Color.FromRgb(56,70,94)),BorderThickness=new Thickness(1),Child=shell};
    }
    public static void Error(string message)
    {CreateError(message).ShowDialog();}
    public static Window CreateError(string message)
    {
        var dialog=new Window{Title="Infinity — error",Width=600,Height=260,WindowStartupLocation=WindowStartupLocation.CenterScreen};Apply(dialog);
        var panel=new DockPanel{Margin=new Thickness(20)};var close=new Button{Content="Close",HorizontalAlignment=HorizontalAlignment.Right,MinWidth=100};close.Click+=(_,_)=>dialog.Close();DockPanel.SetDock(close,Dock.Bottom);panel.Children.Add(close);panel.Children.Add(new TextBox{Text=message,IsReadOnly=true,TextWrapping=TextWrapping.Wrap,VerticalScrollBarVisibility=ScrollBarVisibility.Auto});Wrap(dialog,panel);return dialog;
    }
